import type { ExportedHandler } from "@cloudflare/workers-types";
// @ts-expect-error This JavaScript entry point is generated by OpenNext.
import nextWorker from "./.open-next/worker.js";

type WorkerEnv = {
  CLOUD_INTERNAL_SECRET?: string;
  CLOUD_ORIGIN?: string;
};

export default {
  fetch: nextWorker.fetch,
  async scheduled(_event, env, ctx) {
    if (!env.CLOUD_INTERNAL_SECRET) return;
    const url = new URL("/api/internal/billing", env.CLOUD_ORIGIN || "https://cloud.kernell.ru");
    // Invoke OpenNext directly so the route also works before a domain is attached.
    const response: Response = await nextWorker.fetch(new Request(url, {
      method: "POST",
      headers: { Authorization: `Bearer ${env.CLOUD_INTERNAL_SECRET}` },
    }), env, ctx);
    if (!response.ok) {
      await response.body?.cancel();
      throw new Error(`Scheduled Cloud maintenance returned HTTP ${response.status}.`);
    }
    await response.arrayBuffer();
  },
} satisfies ExportedHandler<WorkerEnv>;
